// EBS C&I peak-shaving scenario (generated by tools/export_ebs_scenario.py from peaksure/ebs_scenario.py).
// Display helpers only: every state below is read from the exported simulation frames, never invented.
import { summarizeCommitment, CommitmentSummary } from "./commitment";

export interface EbsFrame { minute: number; power_kw: number; bypassed_cells: number; block_online: boolean; soc_b64: string; active_b64: string }
export interface EbsRun { delivered_kwh?: number; energy_kwh?: number; fulfilled?: boolean; stop_min: number | null; stop_cell: number | null;
  stop_reason: string | null; first_bypass_min: number | null; bypassed_cells?: number; stranded_kwh?: number; trace: EbsFrame[] }
export interface EbsHardware { commit_kw: number; commit_energy_kwh: number; chance: number; belief_p5: number; belief_p50: number;
  belief_p95: number; status: CommitmentSummary["status"]; outcome: EbsRun & { delivered_kwh: number; fulfilled: boolean }; drain: EbsRun & { energy_kwh: number; stranded_kwh: number } }
export interface EbsCase { weak_factor: number; window_h: number; start_he: number; diagnosis_cell: number; true_weakest_cell: number; fixed: EbsHardware; bypass: EbsHardware }
export interface EbsScenarioFile {
  title: string; use_case: string; profiles: Record<string, string>; rated_kw: number; rated_kwh: number; eta: number; alpha: number;
  n_min: number; cells: number; dc_floor_v: number; r_on_ohm: number; demand_charge: Record<string, number>;
  flags: Record<string, [string, string]>; cases: EbsCase[];
}

export type EbsCellState = "normal" | "approaching" | "limiting" | "bypassed" | "idle";
export const EBS_STATE_COLOR: Record<EbsCellState, string> = {
  normal: "#3fbf7f", approaching: "#e8c547", limiting: "#ef4a3c", bypassed: "#8a949c", idle: "#33414a",
};
export const EBS_STATE_LABEL: Record<EbsCellState, string> = {
  normal: "normal (in circuit)", approaching: "approaching empty (< 15% charge, in circuit)",
  limiting: "limiting: empty cell that stopped the fixed string", bypassed: "bypassed (string still running)",
  idle: "idle: block stopped, charge left in cell",
};
export const APPROACH_SOC = 0.15;
export const DIAGNOSIS_COLOR = "#4aa3ff";

export const decode = (s: string) => {
  const bin = typeof atob === "function" ? atob(s) : Buffer.from(s, "base64").toString("binary");
  return Uint8Array.from(bin, (c) => c.charCodeAt(0));
};

/** Frame at minutes since the window start (clamped: before start = initial state, after end = last frame). */
export function frameAt(trace: EbsFrame[], m: number): EbsFrame {
  if (m <= trace[0].minute) return trace[0];
  let best = trace[0];
  for (const f of trace) { if (f.minute <= m) best = f; else break; }
  return best;
}

export function cellStates(frame: EbsFrame, bypassHw: boolean, started: boolean): EbsCellState[] {
  const soc = decode(frame.soc_b64), act = decode(frame.active_b64);
  return Array.from(soc, (q, i) => {
    const s = q / 255;
    if (!frame.block_online && started) return !bypassHw && s <= 0.004 ? "limiting" : "idle";
    if (!act[i]) return "bypassed";
    return s < APPROACH_SOC && started ? "approaching" : "normal";
  });
}

export function countStates(states: EbsCellState[]): Record<EbsCellState, number> {
  const c: Record<EbsCellState, number> = { normal: 0, approaching: 0, limiting: 0, bypassed: 0, idle: 0 };
  for (const s of states) c[s]++;
  return c;
}

/** Cells whose engine state or charge differs between the two batteries at the same minute. */
export function diffMask(a: EbsFrame, b: EbsFrame, tol = 0.02): boolean[] {
  const sa = decode(a.soc_b64), sb = decode(b.soc_b64), aa = decode(a.active_b64), ab = decode(b.active_b64);
  return Array.from(sa, (_, i) => aa[i] !== ab[i] || a.block_online !== b.block_online || Math.abs(sa[i] - sb[i]) / 255 > tol);
}

export function summary(f: EbsScenarioFile, c: EbsCase, hw: "fixed" | "bypass"): CommitmentSummary {
  const h = c[hw];
  return summarizeCommitment({ startHe: c.start_he, windowH: c.window_h, powerKw: h.commit_kw, expKw: 0 },
    { samples: new Float64Array(0), p5: h.belief_p5, p50: h.belief_p50, p95: h.belief_p95, pAvail: f.rated_kw },
    f.rated_kw, f.rated_kwh, f.eta);
}

/** Stage minutes (since window start) taken from engine output; null when the stage does not happen. */
export function stages(run: { fixed: EbsRun; bypass: EbsRun }, endMin: number) {
  let limit: number | null = run.fixed.stop_min !== null && run.fixed.stop_cell !== null ? run.fixed.stop_min : null;
  if (limit === null) {
    for (const fr of run.fixed.trace) {
      const soc = decode(fr.soc_b64);
      if (fr.block_online && Math.min(...Array.from(soc)) / 255 < APPROACH_SOC) { limit = fr.minute; break; }
    }
  }
  return { before: -15, limit, bypass: run.bypass.first_bypass_min, result: endMin };
}

/** Monthly demand-charge reduction if the billing peak falls inside the window (upper bound) and the commitment holds. */
export const demandValue = (h: EbsHardware, usdPerKwMonth: number) => (h.outcome.fulfilled ? h.commit_kw * usdPerKwMonth : 0);
